"""Round 109 theorist, T5 / H-023: in model M1 (E-284) the quotient N = kM / I (I generated by the two Theta letters and their differentials)
should be the FREE dg algebra on the three survivors fbar = m(None,f,None) (deg 1, loop at i), u = m(a,f,None) (deg 0, i->j), v = a* (deg 0, j->i)
after eliminating the pivot pairs (theta1 <-> bbar = m(None,b,None)) and (theta2 <-> m(a,b,None)).  Check: for every cell (weight <= W, src, tgt, degree)
dim kM - dim I equals the number of words in {fbar, u, v}.  This tests stage 1 only (a dimension statement); it prints no differential and does not test H(I) = 0 or H(N).
Usage (repo root): .venv/bin/python -W ignore workshop/rounds/109/theorist_m1free.py [WMAX] [ctrl]"""
import importlib.util, sys
sp = importlib.util.spec_from_file_location('lf', 'workshop/rounds/106/theorist_loopfilt.py')
lf = importlib.util.module_from_spec(sp); sp.loader.exec_module(lf)
W = int(sys.argv[1]) if len(sys.argv) > 1 else 9
q = lf.MODELS['M1_loop1_dphi=ba'](); m, letters, wt = lf.setup(q)
theta = [L for L in letters if L[0] == 'm' and L[3] is not None]
dth = {L: m.partial({(L,): 1}) for L in theta}
surv = [('m', None, 'f', None), ('m', 'a', 'f', None), ('s', 'a')]
if len(sys.argv) > 2 and sys.argv[2] == 'ctrl': surv = [('m', None, 'f', None), ('m', 'a', 'f', None), ('m', 'a', 'b', None), ('s', 'a')]   # planted error: keep a pivot
def count_free(s, t, Wt):
    out = {}
    sub = [L for L in letters if L in surv]
    def rec(cur, v, w):
        if w == Wt and v == t and cur: out[sum(m.deg(x) for x in cur)] = out.get(sum(m.deg(x) for x in cur), 0) + 1
        if len(cur) > 3 * (Wt + 2) + 2: return
        for L in sub:
            if m.src(L) == v and w + wt(L) <= Wt + 1:
                cur.append(L); rec(cur, m.tgt(L), w + wt(L)); cur.pop()
    rec([], s, 0); return out
bad = 0; cells = 0
for Wt in range(1, W + 1):
    for s in range(2):
        for t in range(2):
            ws = lf.words(m, letters, wt, s, t, Wt)
            if not ws: continue
            bydeg = {}
            for w in ws: bydeg.setdefault(m.wdeg(w), []).append(w)
            piv_d = {}
            for d, L in bydeg.items():
                piv = {}
                for w in L:
                    if any(x in dth for x in w): lf.reduce_into(piv, {w: 1})
                piv_d[d] = piv
            for d1, L in bydeg.items():
                for w in L:
                    for k, x in enumerate(w):
                        if x in dth:
                            piv = piv_d.setdefault(d1 - 1, {})
                            lf.reduce_into(piv, {w[:k] + u + w[k+1:]: c for u, c in dth[x].items()})
            free = count_free(s, t, Wt)
            for d in set(bydeg) | set(piv_d) | set(free):
                nN = len(bydeg.get(d, [])) - len(piv_d.get(d, {}))
                cells += 1
                if nN != free.get(d, 0):
                    bad += 1; print('MISMATCH', (Wt, s, t, d), 'dim kM/I =', nN, 'free words =', free.get(d, 0))
print('cells', cells, 'mismatches', bad)
